mapper.select:
SELECT DISTINCT v.* FROM video v
-- 条件1：必须是电视剧主分类 c_id=14
WHERE EXISTS (
SELECT 1 FROM video_category vc_main
WHERE vc_main.v_id = v.id AND vc_main.c_id = #{mainCid}
)
-- 条件2：列表里每一个cid，视频都必须拥有（交集，全部满足）

    AND EXISTS (
    SELECT 1 FROM video_category vc
    WHERE vc.v_id = v.id AND vc.c_id = #{cid}
    )

SELECT c.id,c.name FROM video_category vc
                            LEFT JOIN category c ON vc.c_id = c.id
WHERE vc.v_id = #{vid}
